sys_script_client.script:
function onSubmit() {
    var valid = true;

    if (g_form.getValue('vehicle') === '') {
        g_form.addErrorMessage('Vehicle is required before submitting.');
        valid = false;
    }

    if (g_form.getValue('service_type') === '') {
        g_form.addErrorMessage('Service Type is required before submitting.');
        valid = false;
    }

    if (g_form.getValue('service_date') === '') {
        g_form.addErrorMessage('Service Date is required before submitting.');
        valid = false;
    }

    if (g_form.getValue('status') === 'cancelled' && g_form.getValue('cancellation_reason') === '') {
        g_form.addErrorMessage('Cancellation Reason is required when status is Cancelled.');
        valid = false;
    }

    return valid;
}
